package com.gear66me.galaxyviewer10e;
import android.app.*; import android.content.*; import android.graphics.Color; import android.graphics.Typeface; import android.net.Uri; import android.os.*; import android.view.View; import android.webkit.*; import android.widget.TextView;
public final class MainActivity extends Activity { private WebView web; @Override protected void onCreate(Bundle b){super.onCreate(b);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_FULLSCREEN|View.SYSTEM_UI_FLAG_HIDE_NAVIGATION|View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY|View.SYSTEM_UI_FLAG_LAYOUT_FULLSCREEN|View.SYSTEM_UI_FLAG_LAYOUT_HIDE_NAVIGATION|View.SYSTEM_UI_FLAG_LAYOUT_STABLE);open();} private void open(){web=new WebView(this);web.setBackgroundColor(Color.BLACK);WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setDatabaseEnabled(true);s.setAllowFileAccess(true);s.setAllowContentAccess(false);s.setAllowFileAccessFromFileURLs(true);s.setAllowUniversalAccessFromFileURLs(true);s.setMediaPlaybackRequiresUserGesture(false);s.setCacheMode(WebSettings.LOAD_DEFAULT);s.setUserAgentString(s.getUserAgentString()+" GalaxyViewer10E/10E-generic");web.setWebChromeClient(new WebChromeClient());web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){Uri u=r.getUrl();String q=u==null?"":u.getScheme();return !("https".equalsIgnoreCase(q)||"file".equalsIgnoreCase(q));}@Override public void onReceivedError(WebView v,WebResourceRequest r,WebResourceError e){if(r.isForMainFrame())fatal("LOAD ERROR: "+e.getDescription());}});web.setDownloadListener((url,ua,cd,mime,len)->{try{Uri u=Uri.parse(url);if(!"https".equalsIgnoreCase(u.getScheme()))return;DownloadManager.Request q=new DownloadManager.Request(u);q.setNotificationVisibility(DownloadManager.Request.VISIBILITY_VISIBLE_NOTIFY_COMPLETED);q.setDestinationInExternalPublicDir(Environment.DIRECTORY_DOWNLOADS,URLUtil.guessFileName(url,cd,mime));((DownloadManager)getSystemService(Context.DOWNLOAD_SERVICE)).enqueue(q);}catch(Exception ignored){}});setContentView(web);web.loadUrl("file:///android_asset/index.html");} private void fatal(String m){runOnUiThread(()->{TextView t=new TextView(this);t.setTypeface(Typeface.createFromAsset(getAssets(),"artwork/Space-Age.otf"));t.setText("GALAXY VIEWER 10E\n\n"+m);t.setTextColor(Color.WHITE);t.setBackgroundColor(Color.BLACK);t.setTextSize(16);t.setPadding(40,40,40,40);setContentView(t);});} @Override public void onBackPressed(){if(web!=null&&web.canGoBack())web.goBack();else super.onBackPressed();}}
